const clamp=(v,min,max)=>Math.max(min,Math.min(max,v));
const random=(a,b)=>a+Math.random()*(b-a), randInt=(a,b)=>Math.floor(random(a,b+1));
const shuffle=arr=>{let a=[...arr];for(let i=a.length-1;i>0;i--){const j=randInt(0,i);[a[i],a[j]]=[a[j],a[i]]}return a};
