const plain=v=>!!v&&typeof v==='object'&&!Array.isArray(v);
const safeNumber=v=>Number.isSafeInteger(v)&&v>=0;
function safeTree(v,depth=0){if(depth>32)return false;if(v===null||typeof v==='string'||typeof v==='boolean')return true;if(typeof v==='number')return Number.isFinite(v);if(Array.isArray(v))return v.every(x=>safeTree(x,depth+1));return plain(v)&&Object.keys(v).every(k=>!['__proto__','constructor','prototype'].includes(k)&&safeTree(v[k],depth+1))}
function normalizeBackup(d){if(!plain(d)||!Array.isArray(d.profiles)||!safeTree(d))throw Error('backup');d.profiles=d.profiles.map(p=>{if(!plain(p))throw Error('profile');return {stats:{},mistakes:{},aquarium:{pearls:0,theme:'Dan'},options:{},paint:null,...p}});if(!validBackup(d))throw Error('backup');d.settings={sound:true,reducedMotion:false,...d.settings};d.settings.sound=d.settings.sound!==false;d.settings.reducedMotion=!!d.settings.reducedMotion;d.profiles=d.profiles.map(p=>({...freshProfile(),...p,stats:p.stats||{},mistakes:p.mistakes||{},aquarium:{pearls:0,theme:'Dan',...p.aquarium},options:p.options||{}}));if(!d.profiles.some(p=>p.id===d.active))d.active=d.profiles[0].id;return d}
function load(){try{storedRaw=localStorage.getItem(STORE);if(storedRaw!==null){try{return normalizeBackup(JSON.parse(storedRaw))}catch(_){recoveryRaw=storedRaw;storageIssue='corrupt';storageAvailable=false}}}catch(_){storageAvailable=false;storageIssue='unavailable'}return initial()}
