function storageStatus(){const el=$('.offline');if(el){el.innerHTML=storageAvailable?'<i></i> Lokalno spremanje':'<i style="background:#f3ba72"></i> Spremanje zaustavljeno'}let a=$('#storageAlert');if(!storageAvailable){if(!a){a=document.createElement('div');a.id='storageAlert';a.className='notice rc-storage';a.setAttribute('role','alert');$('.topbar')?.after(a)}if(a){const msg=storageText();if(a.dataset.msg!==msg){a.dataset.msg=msg;a.innerHTML=`<span>${escapeHTML(msg)}</span><button type="button" class="secondary" id="rcExport">Izvezi podatke</button>${recoveryRaw!==null?'<button type="button" class="secondary" id="rcRaw">Izvorna kopija</button>':''}${storageIssue==='conflict'?'<button type="button" class="secondary" id="rcReload">Ponovno učitaj</button>':''}`;$('#rcExport').onclick=()=>exportBackup();if($('#rcRaw'))$('#rcRaw').onclick=()=>download('kids-world-izvorni-podaci.json',new Blob([recoveryRaw],{type:'application/json'}));if($('#rcReload'))$('#rcReload').onclick=()=>{if(confirm('Ponovno učitati zadnje spremljene podatke? Nespremljene promjene ove kartice će se izgubiti.'))location.reload()}}}}else a?.remove()}
function save({recover=false}={}){try{if(storageIssue==='conflict'||(storageIssue==='corrupt'&&!recover)){storageAvailable=false;storageStatus();return false}const actual=localStorage.getItem(STORE);if(actual!==storedRaw){storageIssue='conflict';storageAvailable=false;storageStatus();return false}const raw=JSON.stringify(data);if(raw!==storedRaw)localStorage.setItem(STORE,raw);storedRaw=raw;storageAvailable=true;storageIssue='';recoveryRaw=null}catch(e){storageAvailable=false;if(storageIssue!=='corrupt')storageIssue='unavailable'}storageStatus();return storageAvailable}
