async function toggleScreen(){if(document.fullscreenElement){try{await document.exitFullscreen()}catch(_){toast('Za izlaz koristi naredbu preglednika.')}screenSync();return}if(document.body.classList.contains('kw-focus')){document.body.classList.remove('kw-focus');screenSync();return}if(document.fullscreenEnabled&&document.documentElement.requestFullscreen){try{await document.documentElement.requestFullscreen();screenSync();return}catch(_){}}document.body.classList.add('kw-focus');screenSync();toast('Prošireni prikaz · cijeli zaslon nije dostupan u ovom pregledniku.');}
