function sound(type='good'){if(!data.settings.sound)return;try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;ac=ac||new Audio();if(ac.state==='suspended')ac.resume().catch(()=>{});const tones={good:[660,880],bad:[240,180],tap:[460],star:[880,1100,1320],win:[523,659,784,1046],pop:[780,1160],hit:[150,100],power:[440,660,880]}[type]||[440];const now=ac.currentTime;tones.forEach((f,i)=>{const o=ac.createOscillator(),g=ac.createGain();o.type=type==='bad'||type==='hit'?'triangle':'sine';o.frequency.value=f;const t=now+i*.075;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.055,t+.009);g.gain.exponentialRampToValueAtTime(.001,t+.11);o.connect(g);g.connect(ac.destination);o.start(t);o.stop(t+.12)})}catch(e){}}
