function bestScore(p,id){const b=p.stats[id]?.best||{};return Math.max(0,...Object.entries(b).filter(([k])=>!k.startsWith('avantura')).map(([,v])=>Number(v)).filter(Number.isFinite))}
function totals(p){return Object.values(p.stats).reduce((a,s)=>({plays:a.plays+(s.plays||0),seconds:a.seconds+(s.seconds||0)}),{plays:0,seconds:0})}
