function flushFamily(c,force=false){if(!c?.familyStarted)return;const now=performance.now(),delta=Math.max(0,(now-c.familyLast)/1000);c.familyLast=now;if(!c.paused&&!document.hidden)c.familyPending+=Math.min(delta,2.5);if(force||c.familyPending>=10){if(c.familyPending>0){F.record(c.familyProfile,c.id,{seconds:c.familyPending});if(c.life){const s=c.familyProfile.stats.dino;if(s)s.seconds=(Number(s.seconds)||0)+c.familyPending;}c.familyPending=0;save()}}const f=F.ensure(c.familyProfile),limit=f.dailyMinutes;if(limit&&f.reminded!==F.day()&&F.today(c.familyProfile)+c.familyPending>=limit*60){f.reminded=F.day();save();toast('Vrijeme za mali predah! Igru mo\u017ee\u0161 nastaviti kad \u017eeli\u0161.')}}
function parentContent(){const pr=data.profiles.find(x=>x.id===familySelected)||profile();familySelected=pr.id;const f=F.ensure(pr),r=F.report(pr,familyPeriod),t=r.total,math=['balloons','math'].reduce((a,id)=>({correct:a.correct+(r.games[id]?.correct||0),wrong:a.wrong+(r.games[id]?.wrong||0)}),{correct:0,wrong:0}),today=F.today(pr),limit=f.dailyMinutes;const ds=familyPeriod==='all'?F.report(pr,'7').daily:r.daily,chartMax=Math.max(1,...ds.map(d=>d.seconds));const games=catalog.map(g=>({g,s:r.games[g.id]||F.blank()}));const favorite=[...games].sort((a,b)=>b.s.seconds-a.s.seconds)[0];const timeTotal=Math.max(1,t.seconds);return `<div class="page-intro family-intro"><div><div class="eyebrow">PRIVATNO NA OVOM URE\u0110AJU</div><h1>Roditeljski kutak</h1><p>Prati napredak, navike i vrijeme igranja bez usporedbe djece.</p></div><label>Profil<select id="familyProfile">${data.profiles.map(p=>`<option value="${escapeHTML(p.id)}" ${p.id===pr.id?'selected':''}>${escapeHTML(p.avatar+' '+p.name)}</option>`).join('')}</select></label></div><div class="family-filter" role="group" aria-label="Razdoblje">${[['7','Zadnjih 7 dana'],['30','Zadnjih 30 dana'],['all','Ukupno']].map(([k,n])=>`<button class="${familyPeriod===k?'secondary':'ghost'}" data-family-period="${k}">${n}</button>`).join('')}<button id="familyCSV" class="ghost">\u2193 Izvezi CSV</button></div><div class="family-kpis">${[['Aktivno igranje',F.duration(t.seconds),'\u23f1'],['Spremljene partije',Math.floor(t.plays),'\u25b6'],['Matemati\u010dka to\u010dnost',F.accuracy(math.correct,math.wrong),'\u2713'],['Dovr\u0161ene avanture',Math.floor(t.journeys),'\u2726']].map(([label,val,icon])=>`<div class="metric family-kpi"><span>${icon}</span><div><div class="caption">${label}</div><strong>${val}</strong></div></div>`).join('')}</div><div class="family-columns"><section class="panel"><h2>Aktivnost po danima</h2><p class="muted small">${familyPeriod==='all'?'Graf prikazuje posljednjih 7 dana.':'Aktivne minute po lokalnom datumu.'}</p><div class="family-chart" style="--days:${ds.length}">${ds.map(d=>`<button type="button" class="family-bar" data-family-day="${d.date}" data-family-seconds="${d.seconds}" aria-label="${d.date}: ${F.duration(d.seconds)}" title="${d.date}: ${F.duration(d.seconds)}"><span class="family-bar-track"><i style="height:${d.seconds/chartMax*100}%"></i></span><small>${d.date.slice(8)}.${d.date.slice(5,7)}.</small></button>`).join('')}</div><div class="family-chart-detail" id="familyDayDetail">Odaberi stupac za to\u010dno vrijeme igranja.</div><div class="family-note">${t.seconds?`Najvi\u0161e vremena: ${favorite.g.name}`:'Jo\u0161 nema aktivnosti u odabranom razdoblju.'}</div></section><section class="panel family-reminder"><h2>Vrijeme za predah</h2><p class="muted small">Dnevni podsjetnik za ovaj profil. Ne zaklju\u010dava igru ni ure\u0111aj.</p><div class="family-today"><strong>${F.duration(today)}</strong><span>danas${limit?' / '+limit+' min':''}</span></div><div class="progress-track"><div class="progress-fill" style="width:${limit?Math.min(100,today/(limit*60)*100):0}%"></div></div><div class="dl-parent-setting"><label for="familyDinoOffline"><strong>Dino Life · potrebe izvan aplikacije</strong><input id="familyDinoOffline" class="switch" type="checkbox" ${f.dinoOffline===true?'checked':''}></label><p class="small muted">Isključeno prema zadanim postavkama. Ako uključiš, potrebe se blago mijenjaju dok je dino svijet zatvoren. Nema smrti ni gubitka iskustva.</p></div><label for="familyLimit">Podsjeti nakon</label><select id="familyLimit">${[0,15,20,30,45,60,90,120].map(n=>`<option value="${n}" ${limit===n?'selected':''}>${n?n+' minuta':'Isklju\u010deno'}</option>`).join('')}</select><p class="small muted">Pauze i vrijeme izvan igre ne ubrajaju se. Dnevni zapis zapo\u010dinje s v0.9.3.</p></section></div><div class="section-heading"><h2>Detaljno po igrama</h2></div><div class="panel family-table-panel"><div class="family-table-wrap"><table class="stat-table family-table"><thead><tr><th>Igra</th><th>Vrijeme</th><th>Partije</th><th>Dovr\u0161ene</th><th>To\u010dno / neto\u010dno</th><th>Avantura</th></tr></thead><tbody>${games.map(({g,s})=>`<tr><td>${g.emoji} ${g.name}<div class="family-mini"><i style="width:${Math.min(100,s.seconds/timeTotal*100)}%"></i></div></td><td data-label="Vrijeme">${F.duration(s.seconds)}</td><td data-label="Partije">${Math.floor(s.plays)}</td><td data-label="Dovr\u0161ene">${Math.floor(s.wins)}</td><td data-label="To\u010dno / neto\u010dno">${s.correct||s.wrong?Math.floor(s.correct)+' / '+Math.floor(s.wrong):'\u2014'}</td><td data-label="Avantura">Razina ${J.level(pr,g.id)}<small>${Math.floor(s.journeys)} dovr\u0161eno u razdoblju</small></td></tr>`).join('')}</tbody></table></div><p class="family-note">${Math.floor(t.discarded)} prekinutih sesija u razdoblju. Prekinute sesije doprinose vremenu, ali ne rezultatima. Trenuta\u010dna razina je ukupna, neovisno o filtru.</p></div><section class="panel family-math"><h2>Matematika i u\u010denje</h2><div class="two-col"><div class="metric"><div class="caption">To\u010dni odgovori</div><strong>${Math.floor(math.correct)}</strong></div><div class="metric"><div class="caption">Poku\u0161aji s pogre\u0161kom</div><strong>${Math.floor(math.wrong)}</strong></div></div><p class="family-note">${r.legacy?'Ukupni podaci uklju\u010duju stare spremljene rezultate. Za ranije verzije nemamo datume igranja.':'Dnevna povijest bilje\u017ei se od v0.9.3, bez naknadnog izmi\u0161ljanja datuma.'} Podaci se spremaju na ovom ure\u0111aju i mogu se prenijeti sigurnosnom kopijom.</p></section>`}
function bindParents(){const pr=data.profiles.find(x=>x.id===familySelected)||profile();const offline=$('#familyDinoOffline');if(offline)offline.onchange=()=>{F.ensure(pr).dinoOffline=offline.checked;const now=Date.now();for(const pet of Object.values(pr.dino||{}))if(pet&&typeof pet==='object'&&pet.lifeVersion===1)pet.lastSeen=now;save();toast('Postavka Dino Life je spremljena.')};$('#familyProfile').onchange=e=>{familySelected=e.target.value;render('parents')};$$('[data-family-period]').forEach(b=>b.onclick=()=>{familyPeriod=b.dataset.familyPeriod;render('parents')});$$('[data-family-day]').forEach(b=>b.onclick=()=>{const [y,m,d]=b.dataset.familyDay.split('-');$('#familyDayDetail').textContent=`${d}.${m}.${y}. \u00b7 ${F.duration(Number(b.dataset.familySeconds))}`;$$('[data-family-day]').forEach(x=>x.classList.toggle('chosen',x===b))});$('#familyLimit').onchange=e=>{const f=F.ensure(pr);f.dailyMinutes=Number(e.target.value);f.reminded='';save();render('parents');toast('Podsjetnik je spremljen.')};$('#familyCSV').onclick=()=>download('kids-world-statistika.csv',new Blob([F.csv(pr,familyPeriod,catalog)],{type:'text/csv;charset=utf-8'}));}

function render(p='home'){dispose();setPage(p);const pr=profile(),t=totals(pr);let content='';
if(p==='home'){content=`<div class="hero"><div><div class="eyebrow">✦ DOBRO DOŠAO U AVANTURU</div><h1>Igraj se.<br>Uči. Istražuj!</h1><p>Dvanaest svjetova i beskrajne avanture. Svaka igra ima vlastiti napredak, a slobodna igra ostaje otvorena.</p><button class="primary" data-nav="games">Odaberi igru <span>→</span></button></div>${heroArt}</div><div class="stats-strip"><div class="metric"><div class="metric-icon">🚀</div><div class="metric-body"><div class="caption">Razina ${level(pr)} · Istraživač</div><strong>${pr.xp%100} / 100 XP</strong><div class="progress-track"><div class="progress-fill" style="width:${pr.xp%100}%"></div></div></div></div><div class="metric"><div class="metric-icon">🏅</div><div><div class="caption">Medalje</div><strong>${medals.filter(m=>m[3](pr)).length} / ${medals.length}</strong></div></div><div class="metric"><div class="metric-icon">🎮</div><div><div class="caption">Odigrano</div><strong>${t.plays} ${t.plays===1?'igra':t.plays%10>=2&&t.plays%10<=4&&!(t.plays%100>=12&&t.plays%100<=14)?'igre':'igara'}</strong></div></div></div><div class="section-heading"><div><h2>Odaberi svoj svijet</h2><p>Igre za učenje, opuštanje i zabavu</p></div><button class="ghost" data-nav="games">Sve igre →</button></div><div class="mission-home"><div><b>🎁 Posebne misije i nagrade</b><p>${R.available(pr)?R.available(pr)+' nagrada spremno za preuzimanje':'Istraži 42 nova izazova.'}</p></div><button class="secondary" data-nav="rewards">Otvori album →</button></div>${KW.connected?.home(pr)||''}${groupedGames()}`}
else if(p==='connected')content=KW.connected.render(pr);
else if(p==='games')content=`<div class="page-intro"><h1>Sve igre</h1><p>Odaberi avanturu. Sve su besplatne, bez reklama i bez zaključavanja.</p></div>${groupedGames()}`;
else if(p==='rewards')content=`<div class="page-intro"><h1>Tvoja kolekcija</h1><p>Medalje dobivaš igrom i istraživanjem. Nema dnevnih obaveza ni kazni.</p></div><div class="stats-strip"><div class="metric"><div class="metric-icon">⭐</div><div><div class="caption">Zvjezdice</div><strong>${pr.stars}</strong></div></div><div class="metric"><div class="metric-icon">🏆</div><div><div class="caption">Medalje</div><strong>${medals.filter(m=>m[3](pr)).length}/${medals.length}</strong></div></div><div class="metric"><div class="metric-icon">🐚</div><div><div class="caption">Biseri</div><strong>${pr.aquarium.pearls}</strong></div></div></div>${KW.connected?.home(pr)||''}${rewardCenter(pr)}<div class="section-heading"><h2>Medalje</h2></div><div class="reward-grid">${medals.map(m=>`<div class="reward-card ${m[3](pr)?'':'locked'}"><div class="emoji">${m[0]}</div><strong>${m[1]}</strong><p>${m[2]}</p><p>${m[3](pr)?'✓ Osvojeno':'Još nije osvojeno'}</p></div>`).join('')}</div><div class="section-heading"><h2>Akvarij</h2></div><div class="panel"><p>U akvariju biserima automatski otključavaš sedam blaga na 10, 25, 50, 100, 250, 500 i 1000 bisera. Svih pet pozadina odmah je dostupno.</p><button class="secondary" data-game="aquarium" style="margin-top:12px">Otvori akvarij</button></div>`;
else if(p==='parents'){content=parentContent();}
else if(p==='progress'){const bs=pr.stats.balloons||{},ms=pr.stats.math||{},correct=(bs.correct||0)+(ms.correct||0),wrong=(bs.wrong||0)+(ms.wrong||0);content=`<div class="page-intro"><h1>Tvoj napredak</h1><p>Statistika se sprema lokalno, zasebno za svaki profil.</p><button class="secondary parent-link" data-nav="parents">Detaljna statistika i roditeljski kutak &rarr;</button></div><div class="stats-strip"><div class="metric"><div class="metric-icon">🎯</div><div><div class="caption">Matematička točnost (obje igre)</div><strong>${correct+wrong?Math.round(correct/(correct+wrong)*100)+'%':'—'}</strong></div></div><div class="metric"><div class="metric-icon">✓</div><div><div class="caption">Točno / netočno</div><strong>${correct} / ${wrong}</strong></div></div><div class="metric"><div class="metric-icon">⏱</div><div><div class="caption">Aktivno igranje</div><strong>${Math.floor(t.seconds/60)} min</strong></div></div></div><div class="section-heading"><h2>Rezultati po igrama</h2></div><div class="panel"><table class="stat-table"><thead><tr><th>Igra</th><th>Odigrano</th><th>Rekord</th><th>Avantura</th></tr></thead><tbody>${catalog.map(g=>`<tr><td>${g.emoji} ${g.name}</td><td>${pr.stats[g.id]?.plays||0}</td><td>${g.id==='paint'||g.id==='dino'?'—':bestScore(pr,g.id)}</td><td>${g.id==='dino'?escapeHTML(window.KWLife.summary(pr)):`Razina ${J.level(pr,g.id)}`}</td></tr>`).join('')}</tbody></table></div><div class="section-heading"><h2>Rekordi po načinu igre</h2></div><div class="panel">${catalog.filter(g=>Object.keys(pr.stats[g.id]?.best||{}).length&&g.id!=='paint').map(g=>`<h3 style="margin:10px 0 5px">${g.name}</h3>${Object.entries(pr.stats[g.id].best).map(([k,v])=>`<div class="setting-row"><span class="small muted">${escapeHTML(variantLabel(k))}</span><b>${v}</b></div>`).join('')}`).join('')||'<p class="muted">Još nema rezultata. Kreni u prvu avanturu!</p>'}</div>${circuitRecords(pr)}`}
else if(p==='settings')content=`<div class="page-intro"><h1>Postavke</h1><p>Prilagodi Kids World sebi. Nema računa ni slanja podataka na server.</p></div><div class="panel"><h2>Igranje</h2><div class="setting-row"><div><strong>Moj avatar i Connected World</strong><p>Uredi svoj izgled, trgovine i kolekcije.</p></div><button class="secondary" data-nav="connected">Otvori</button></div><div class="setting-row"><div><strong>Roditeljski kutak</strong><p>Vrijeme, napredak i postavke po profilu.</p></div><button class="secondary" data-nav="parents">Otvori</button></div><div class="setting-row"><div><strong>Zvučni efekti</strong><p>Zvukovi odgovora, bonusa i nagrada.</p></div><input class="switch" aria-label="Zvučni efekti" id="soundToggle" type="checkbox" ${data.settings.sound?'checked':''}></div><div class="setting-row"><div><strong>Smanjeno gibanje</strong><p>Mirniji baloni i manje dekorativnih čestica.</p></div><input class="switch" aria-label="Smanjeno gibanje" id="motionToggle" type="checkbox" ${data.settings.reducedMotion?'checked':''}></div><div class="setting-row"><div><strong>Profili igrača</strong><p>Odvojen napredak za do 5 igrača.</p></div><button id="profiles" class="secondary">Profili</button></div></div><div class="section-heading"><h2>Spremanje i sigurnosna kopija</h2></div><div class="panel"><p class="muted" style="line-height:1.5;font-size:13px">Podaci su vezani uz ovaj preglednik i adresu aplikacije. Za prijenos na drugi uređaj izvezi kopiju pa je uvezi na novom uređaju.</p><div class="game-controls"><button id="exportData" class="secondary">Izvezi podatke</button><button id="importData" class="secondary">Uvezi podatke</button><input type="file" id="importFile" accept="application/json,.json" hidden></div><div id="kwMobilePanel"></div><div class="notice">${escapeHTML(storageText())}</div><div class="setting-row"><div><strong>Offline instalacija</strong><p id="offlineStatus">Provjera dostupnosti offline načina…</p></div><button type="button" class="secondary" id="checkUpdate" hidden>Provjeri nadogradnju</button><button type="button" class="primary" id="activateUpdate" hidden>Primijeni nadogradnju</button></div></div>`;
$('#view').innerHTML=content;if(p==='settings')bindSettings();if(p==='parents')bindParents();if(p==='connected')KW.connected.bind(pr,{save,refresh:refreshHeader,toast,sound,render:()=>render('connected'),launch(id,overrides={}){const g=gameById(id);if(g)startGame(id,{...g.defaults,...profile().options[id],...overrides,journey:false});}});}
function variantLabel(k){const map={'garage-training':'Garaža · solo trening','garage-championship':'Garaža · prvenstvo','galaxy':'Galaxy Explorer','avantura-circuit':'Beskrajna avantura · Turbo Circuit',circuit:'Kružna utrka',rex:'Crveni T-Rex',anky:'Zlatni Ankylosaurus',para:'Tirkizni Parasaurolophus',raptor:'Ljubičasti Velociraptor',spino:'Narančasti Spinosaurus',avantura:'Beskrajna avantura',expert:'Napredna',master:'Majstor',endless:'Beskonačno',mixed:'Miješane teme',shapes:'Oblici i boje',sea:'Morski prijatelji',island:'Tropski otok',winter:'Zimska bajka',castle:'Čarobni dvorac',amber:'Zlatni Bronto',violet:'Ljubičasti',jade:'Smaragdni Tricera',easy:'Lagana',normal:'Srednja',hard:'Teška',add:'Zbrajanje',sub:'Oduzimanje',mix:'Miješano',mul:'Množenje',div:'Dijeljenje',practice:'Vježba',timed:'60 s',lives:'Srca',relax:'Bez žurbe',mission:'Voćna misija',animals:'Životinje',fruit:'Voće',vehicles:'Vozila',space:'Svemir',melody:'Čarobna melodija',dance:'Plesni ritam',mint:'Zeleni Bronto',coral:'Ružičasti Tricera',sky:'Plavi Stego',forest:'Čarobna šuma',ocean:'Podvodni svijet',all:'Sve'};return k.split('|').map(x=>map[x]||x).join(' · ')}
function download(name,blob){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function validBackup(d){if(!plain(d)||d.version!==1||!Array.isArray(d.profiles)||d.profiles.length<1||d.profiles.length>5||!safeTree(d)||new Set(d.profiles.map(p=>p?.id)).size!==d.profiles.length||d.settings!=null&&!plain(d.settings))return false;
 const optionalObjects=['family','dino','journeys','fun','learning','connected','rewardClaims','universe','dinoUniverse'];
 return d.profiles.every(p=>plain(p)&&typeof p.id==='string'&&p.id.length>0&&typeof p.name==='string'&&p.name.trim().length>0&&p.name.length<=24&&AVATARS.includes(p.avatar)&&safeNumber(p.xp)&&safeNumber(p.stars)&&plain(p.stats)&&Object.values(p.stats).every(z=>plain(z)&&['plays','seconds','correct','wrong','wins'].every(k=>z[k]==null||typeof z[k]==='number'&&Number.isFinite(z[k])&&z[k]>=0)&&(z.best==null||plain(z.best)&&Object.values(z.best).every(x=>typeof x==='number'&&Number.isFinite(x)&&x>=0)))&&plain(p.aquarium)&&safeNumber(p.aquarium.pearls)&&(!p.paint||Array.isArray(p.paint)&&p.paint.every(plain))&&plain(p.mistakes)&&plain(p.options)&&Object.values(p.options).every(plain)&&optionalObjects.every(k=>p[k]==null||plain(p[k]))&&(p.family?.history==null||plain(p.family.history)&&Object.values(p.family.history).every(d=>plain(d)&&Object.values(d).every(plain)))&&(p.family?.legacy==null||plain(p.family.legacy)&&Object.values(p.family.legacy).every(plain))&&(p.dino==null||Object.values(p.dino).every(plain)));
}
function bindSettings(){$('#soundToggle').onchange=e=>{data.settings.sound=e.target.checked;save();if(e.target.checked)sound('tap')};$('#motionToggle').onchange=e=>{data.settings.reducedMotion=e.target.checked;syncMotion();save()};$('#profiles').onclick=profilesModal;$('#exportData').onclick=exportBackup;$('#importData').onclick=()=>$('#importFile').click();$('#importFile').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>16*1024*1024)throw Error();const d=normalizeBackup(JSON.parse(await f.text()));d.profiles.forEach(p=>{F.ensure(p);window.KWLife.migrate(p)});showModal('<h2>Uvesti kopiju?</h2><p class="muted">Trenutačni profili i napredak bit će zamijenjeni samo ako spremanje uspije. Preporučujemo izvoz postojeće kopije.</p><div class="game-controls"><button id="confirmImport" class="primary">Uvezi</button><button id="backupBeforeImport" class="secondary">Izvezi postojeće podatke</button><button id="cancelImport">Odustani</button></div>');$('#backupBeforeImport').onclick=exportBackup;$('#confirmImport').onclick=()=>{const previous=data;data=d;const ok=save({recover:true});if(!ok)data=previous;syncMotion();closeModal();render('settings');toast(ok?'Kopija je uvezena.':'Uvoz nije spremljen. Prethodni profil je zadržan.')};$('#cancelImport').onclick=closeModal}catch(err){toast('Datoteka nije valjana Kids World sigurnosna kopija.')}finally{e.target.value=''}};updateOfflineStatus();window.KWMobile?.bind({exportBackup,makeBackup:()=>new File([JSON.stringify(data)],`kids-world-backup-${F.day()}.json`,{type:'application/json'})})}
let registration=null,offlineMessage='Offline način zahtijeva HTTPS ili lokalni server.',applyUpdate=false;
function updateOfflineStatus(){const el=$('#offlineStatus');if(el)el.textContent=registration?.waiting?'Nova verzija spremna. Najprije spremi napredak, zatim primijeni nadogradnju.':offlineMessage;const b=$('#checkUpdate'),a=$('#activateUpdate');if(b){b.hidden=!registration;b.onclick=async()=>{try{await registration.update();offlineMessage=registration.waiting?'Nova verzija dostupna.':'Provjera nadogradnje završena.'}catch(_){offlineMessage='Nadogradnja nije dostupna bez mreže.'}updateOfflineStatus()}}if(a){a.hidden=!registration?.waiting;a.onclick=()=>{if(current||!save())return;applyUpdate=true;registration.waiting?.postMessage({type:'SKIP_WAITING'})}}}
function initOffline(){if(!('serviceWorker'in navigator)||!(location.protocol==='https:'||location.hostname==='localhost'||location.hostname==='127.0.0.1')){updateOfflineStatus();return}offlineMessage='Priprema offline resursa…';navigator.serviceWorker.addEventListener('controllerchange',()=>{if(applyUpdate){applyUpdate=false;location.reload()}else updateOfflineStatus()});navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).then(r=>{registration=r;function watch(){const w=r.installing;w?.addEventListener('statechange',()=>{if(w.state==='installed'||w.state==='activated')updateOfflineStatus();if(w.state==='redundant'){offlineMessage='Offline priprema nije dovršena.';updateOfflineStatus()}})}r.addEventListener('updatefound',watch);watch();navigator.serviceWorker.ready.then(()=>{offlineMessage='Offline resursi pripremljeni. Provjeri pokretanje bez interneta.';updateOfflineStatus()});updateOfflineStatus()}).catch(()=>{offlineMessage='Offline priprema nije uspjela. Provjeri vezu i ponovno otvori aplikaciju.';updateOfflineStatus()})}
