function updateJourney(c,items=null,explicit=null){const m=c.journeyPlan,el=$('#journeyLiveStatus'),bar=$('#journeyMeter'),button=$('#journeyFinish');if(!m||!el||!bar)return;let value=0,total=0,label='',ready=false;if(m.goal){const raw=items?.find(([name])=>name===m.metric)?.[1];if(raw===undefined)return;value=Math.max(0,Number(raw)||0);total=m.goal;ready=value>=total;label=ready?'Cilj ostvaren!':`${Math.min(value,total)} / ${total}`;}else if(explicit){({value,total,label}=explicit);}else{const names={balloons:'Zadaci',memory:'Parovi',maze:'Ključevi',puzzle:'Na mjestu',math:'Riješeno',dino:'Misija',music:'Runda'};const raw=items?.find(([name])=>name===names[c.id])?.[1];if(typeof raw!=='string'||!raw.includes('/'))return;[value,total]=raw.split('/').map(Number);if(c.id==='music'){value=Math.max(0,value-1);label=`${value} / ${total} rundi završeno`;}else if(c.id==='maze'&&value>=total)label='Svi ključevi! Pronađi škrinju.';else label=`${value} / ${total}`;}if(!(total>0)||!Number.isFinite(value))return;value=Math.max(0,Math.min(value,total));const key=[value,total,label,ready].join('|');if(c.journeyHUD===key)return;c.journeyHUD=key;el.textContent=label||`${value} / ${total}`;bar.max=total;bar.value=value;bar.setAttribute('aria-valuetext',el.textContent);bar.closest('.journey-meter-wrap').classList.toggle('goal-ready',ready);if(button)button.hidden=!ready;if(ready&&!c.goalCelebrated){c.goalCelebrated=true;sound('power');}}
